 if (!item) return;
+document.getElementById('copyRevision').onclick = async () => {
+    try {
+        await navigator.clipboard.writeText(item.revision);
+        resultStatus.textContent = 'Repository revision copied.';
+    } catch {
+        resultStatus.textContent = 'Could not access the clipboard. Select and copy the visible revision.';
